import{_ as t,o,c as a,a5 as i}from"./chunks/framework.DrDMl0tG.js";const m=JSON.parse('{"title":"World Configuration File","description":"","frontmatter":{},"headers":[],"relativePath":"sections/WorldConfigurationFile.md","filePath":"sections/WorldConfigurationFile.md"}'),d={name:"sections/WorldConfigurationFile.md"};function s(c,e,l,n,r,h){return o(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="world-configuration-file" tabindex="-1">World Configuration File <a class="header-anchor" href="#world-configuration-file" aria-label="Permalink to &quot;World Configuration File&quot;">​</a></h1><p>A RaiSim world configuration file is an XML file with a <code>&lt;raisim&gt;</code> root element. Load it with <code>raisim::World world(&quot;path/to/world.xml&quot;)</code>; see <a href="./WorldSystem.html">World</a>. Example files are in <a href="https://github.com/raisimTech/raisim2Lib/tree/main/rsc/xmlScripts" target="_blank" rel="noreferrer">rsc/xmlScripts</a>.</p><p>The following sections describe the elements the loader reads. Elements and attributes marked (optional) may be omitted. Unmarked elements and attributes are required when their parent element is present. Elements marked (multiple) may appear more than once under the same parent.</p><p>Numbers are written with a <code>.</code> decimal point and no digit grouping, whatever locale the application runs in. Vector-valued attributes (<code>Vec&lt;3&gt;</code>, <code>Vec&lt;4&gt;</code>, <code>VecDyn</code>) are lists of numbers separated by whitespace or by commas, e.g. <code>pos=&quot;0 0 1&quot;</code> or <code>pos=&quot;0, 0, 1&quot;</code>. The token <code>[THIS_DIR]</code> anywhere in the file is replaced by the directory that contains the file, so resource paths can be written relative to the file, e.g. <code>urdf_path=&quot;[THIS_DIR]/../anymal/urdf/anymal.urdf&quot;</code>. A relative <code>urdf_path</code> or <code>include</code> path names a file in the process working directory or, if there is none, a file relative to the folder of the XML file that names it. Other relative paths without <code>[THIS_DIR]</code> are resolved against the process working directory.</p><ol><li><code>raisim</code>: the root element. <ol><li>&lt;attribute&gt; (optional) <code>version</code> [string]: the RaiSim version that wrote the file. The loader does not check it; <code>exportToXml</code> writes <code>2.0.0</code>.</li><li>&lt;child&gt; (optional) <code>material</code>: material pair properties. See <a href="./MaterialSystem.html">Material System</a> for their meaning. <ol><li>&lt;child&gt; (optional) <code>default</code>: the properties used for material pairs without a <code>pair_prop</code> entry. If omitted, the built-in defaults are used. <ol><li>&lt;attribute&gt; <code>friction</code> [float]</li><li>&lt;attribute&gt; <code>restitution</code> [float]</li><li>&lt;attribute&gt; <code>restitution_threshold</code> [float]</li><li>&lt;attribute&gt; (optional, default = <code>friction</code>) <code>static_friction</code> [float]</li><li>&lt;attribute&gt; (optional, default = 1) <code>static_friction_velocity_threshold</code> [float]</li><li>&lt;attribute&gt; (optional, default = 0) <code>rolling_friction</code> [float]</li><li>&lt;attribute&gt; (optional, default = 0) <code>spinning_friction</code> [float]</li></ol></li><li>&lt;child&gt; (optional, multiple) <code>pair_prop</code><ol><li>&lt;attribute&gt; <code>name1</code> [string]</li><li>&lt;attribute&gt; <code>name2</code> [string]</li><li>&lt;attribute&gt; <code>friction</code> [float]</li><li>&lt;attribute&gt; <code>restitution</code> [float]</li><li>&lt;attribute&gt; <code>restitution_threshold</code> [float]</li><li>&lt;attribute&gt; (optional, default = <code>friction</code>) <code>static_friction</code> [float]</li><li>&lt;attribute&gt; (required when <code>static_friction</code> is present, otherwise 1e-3) <code>static_friction_velocity_threshold</code> [float]</li><li>&lt;attribute&gt; (optional, default = 0) <code>rolling_friction</code> [float]</li><li>&lt;attribute&gt; (optional, default = 0) <code>spinning_friction</code> [float]</li></ol></li></ol></li><li>&lt;child&gt; (optional) <code>gravity</code><ol><li>&lt;attribute&gt; <code>value</code> [Vec&lt;3&gt;]: default = <code>0, 0, -9.81</code>, or the gravity of an included file</li></ol></li><li>&lt;child&gt; (optional) <code>timeStep</code>. Only this camelCase tag name is read. <ol><li>&lt;attribute&gt; <code>value</code> [float]: default = 0.005</li></ol></li><li>&lt;child&gt; (optional) <code>erp</code>: (advanced) the spring and damping terms of the contact error dynamics; see <code>World::setERP</code>. <ol><li>&lt;attribute&gt; <code>erp</code> [float]: spring term</li><li>&lt;attribute&gt; <code>erp2</code> [float]: damping term</li></ol></li><li>&lt;child&gt; (optional) <code>simulation</code>: solver, contact-detection and sleeping settings. See <a href="#simulation-settings">Simulation settings</a>.</li><li>&lt;child&gt; (optional) <code>object_class</code>: reusable object templates. See <a href="#object-class">object_class</a>.</li><li>&lt;child&gt; (optional) <code>objects</code>: the objects of the world. See <a href="#object-xml-description">Object XML Description</a>.</li><li>&lt;child&gt; (optional, multiple) <code>tendon</code> and <code>tendon_coupling</code>: see the native world XML section of <a href="./tendons/Reference.html">Tendon API and model files</a>.</li><li>&lt;child&gt; (optional, multiple) <code>wire</code>: legacy length constraint. The loader converts each wire into a two-site tendon; exports write <code>tendon</code> elements instead. See <a href="./Constraints.html">Constraints</a> and the <a href="https://github.com/raisimTech/raisim2Lib/blob/main/rsc/xmlScripts/wire/newtonsCradle.xml" target="_blank" rel="noreferrer">wire example</a>. <ol><li>&lt;attribute&gt; <code>name</code> [string]: wire (tendon) name.</li><li>&lt;attribute&gt; <code>type</code> [string]: <code>stiff</code>, <code>compliant</code>, or <code>custom</code>.</li><li>&lt;attribute&gt; <code>length</code> [float]: nominal length (m), at least 0.</li><li>&lt;attribute&gt; (optional) <code>stretch_type</code> [string]: <code>stretch_only</code>, <code>compression_only</code>, or <code>both</code>. Default: <code>stretch_only</code> for stiff and compliant wires, <code>compression_only</code> for custom wires.</li><li>&lt;attribute&gt; (required for <code>compliant</code>) <code>stiffness</code> [float]</li><li>&lt;attribute&gt; (optional, <code>custom</code> only, default = 0) <code>tension</code> [float]</li><li>&lt;attribute&gt; (optional, default = 0.02) <code>width</code> [float] and (optional, default = <code>1, 1, 1, 1</code>) <code>color</code> [Vec&lt;4&gt;]: appearance.</li><li>&lt;child&gt; <code>object1</code> and <code>object2</code>: the two attachment points. Each has a <code>name</code> [string] attribute naming the attached object and one of the following: <ul><li><code>local_index</code> [int] and <code>pos</code> [Vec&lt;3&gt;]: the local body index (0 for a single-body object) and the attachment point in that body&#39;s frame; or</li><li><code>frame</code> [string] (articulated systems only): the name of the frame to attach to.</li></ul></li></ol></li><li>&lt;child&gt; (optional, multiple) <code>include</code> and <code>params</code>: see <a href="#configuration-template">Configuration Template</a>.</li></ol></li></ol><h2 id="object-xml-description" tabindex="-1">Object XML Description <a class="header-anchor" href="#object-xml-description" aria-label="Permalink to &quot;Object XML Description&quot;">​</a></h2><p>Each child element of <code>objects</code> creates one object. The element name selects the object type (<code>sphere</code>, <code>box</code>, <code>capsule</code>, <code>cylinder</code>, <code>compound</code>, <code>mesh</code>, <code>ground</code>, <code>heightmap</code>, <code>articulatedSystem</code>, <code>deformable</code>, <code>granular</code>) or names an <code>object_class</code> defined in the same file.</p><p>Every object requires a <code>name</code> attribute, and an object with <code>exist=&quot;false&quot;</code> is skipped (see <a href="#configuration-template">Configuration Template</a>).</p><p>The XML reader accepts both the snake_case names documented below and the camelCase aliases used by older examples for common attributes, such as <code>collisionGroup</code>, <code>collisionMask</code>, <code>xSample</code>, <code>ySample</code>, <code>xSize</code>, <code>ySize</code>, <code>centerX</code>, <code>centerY</code>, <code>resDir</code>, <code>urdfPath</code>, <code>fileName</code>, <code>linVel</code>, and <code>angVel</code>.</p><p><code>collision_group</code> and <code>collision_mask</code> accept two notations:</p><ul><li>a plain decimal integer is the raw bitmask, so <code>collision_group=&quot;1&quot;</code> is bit 0 and <code>&quot;-1&quot;</code> sets every bit;</li><li><code>collision[i|j|...]</code> sets bits <code>i</code>, <code>j</code>, ...; for example, <code>collision[1|4|6]</code> is <code>(1 &lt;&lt; 1) | (1 &lt;&lt; 4) | (1 &lt;&lt; 6)</code>, and <code>collision[-1]</code> sets every bit.</li></ul><p>Two objects can collide only if each object&#39;s group shares a bit with the other object&#39;s mask. See <a href="./Contact.html">Contact and Collision</a> for details.</p><h3 id="single-bodies" tabindex="-1">Single bodies <a class="header-anchor" href="#single-bodies" aria-label="Permalink to &quot;Single bodies&quot;">​</a></h3><p><a href="https://github.com/raisimTech/raisim2Lib/blob/main/rsc/xmlScripts/objects/SingleBodies.xml" target="_blank" rel="noreferrer">Example</a></p><p><code>sphere</code>, <code>box</code>, <code>capsule</code>, <code>cylinder</code>, <code>compound</code>, and <code>mesh</code> share the following attributes and children. The type-specific parts follow in the next sections.</p><p><strong>attributes</strong>: <code>name</code> [string], <code>mass</code> [float], (optional, default=1) <code>collision_group</code>, (optional, default=-1) <code>collision_mask</code>, (optional, default <code>default</code>) <code>material</code> [string] (ignored by <code>compound</code>, whose children carry their own materials), (optional) <code>appearance</code> [string], (optional, default <code>dynamic</code>) <code>body_type</code> [string]: <code>dynamic</code>, <code>kinematic</code>, or <code>static</code>, (optional for primitives, default <code>0, 0, 0</code>) <code>com</code> [Vec&lt;3&gt;]: the center of mass in the body frame</p><ol><li>&lt;child&gt; <code>inertia</code>: &lt;attribute&gt; <code>xx</code>, <code>xy</code>, <code>xz</code>, <code>yy</code>, <code>yz</code>, <code>zz</code> [float], the inertia about the center of mass in the body frame. Optional for <code>sphere</code>, <code>box</code>, <code>capsule</code>, and <code>cylinder</code>, which otherwise derive it from the geometry assuming uniform density. Required for <code>mesh</code> and <code>compound</code>: without it their inertia is zero, which is rejected as not positive definite.</li><li>&lt;child&gt; <code>state</code>: &lt;attribute&gt; <code>pos</code> [Vec&lt;3&gt;], (optional, default <code>1, 0, 0, 0</code>) <code>quat</code> [Vec&lt;4&gt;], (optional, default <code>0, 0, 0</code>) <code>lin_vel</code> [Vec&lt;3&gt;], (optional, default <code>0, 0, 0</code>) <code>ang_vel</code> [Vec&lt;3&gt;]</li></ol><h3 id="sphere" tabindex="-1">sphere <a class="header-anchor" href="#sphere" aria-label="Permalink to &quot;sphere&quot;">​</a></h3><ol><li>&lt;child&gt; <code>dim</code>: &lt;attribute&gt; <code>radius</code> [float]</li></ol><h3 id="capsule-and-cylinder" tabindex="-1">capsule and cylinder <a class="header-anchor" href="#capsule-and-cylinder" aria-label="Permalink to &quot;capsule and cylinder&quot;">​</a></h3><ol><li>&lt;child&gt; <code>dim</code>: &lt;attribute&gt; <code>radius</code> [float], <code>height</code> [float]</li></ol><h3 id="box" tabindex="-1">box <a class="header-anchor" href="#box" aria-label="Permalink to &quot;box&quot;">​</a></h3><ol><li>&lt;child&gt; <code>dim</code>: &lt;attribute&gt; <code>x</code> [float], <code>y</code> [float], <code>z</code> [float]: the full side lengths along the body axes</li></ol><h3 id="compound" tabindex="-1">compound <a class="header-anchor" href="#compound" aria-label="Permalink to &quot;compound&quot;">​</a></h3><p>A single rigid body made of several primitive collision shapes. <code>com</code> and the <code>inertia</code> child are required.</p><ol><li><p>&lt;child&gt; <code>children</code>: one element per shape, in any order. Each element is <code>sphere</code>, <code>box</code>, <code>capsule</code>, <code>cylinder</code>, or the name of a compound <code>object_class</code> (whose shapes are inserted at this pose). Other attributes of the shape elements, such as <code>name</code> or <code>mass</code>, are ignored.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;attribute&gt; (optional, default=default) material [string]</span></span>
<span class="line"><span>&lt;attribute&gt; (optional) appearance [string]</span></span>
<span class="line"><span>&lt;child&gt; dim               (not used for an object_class child)</span></span>
<span class="line"><span>  sphere:             &lt;attribute&gt; radius [float]</span></span>
<span class="line"><span>  capsule, cylinder:  &lt;attribute&gt; radius [float], height [float]</span></span>
<span class="line"><span>  box:                &lt;attribute&gt; x [float], y [float], z [float]</span></span>
<span class="line"><span>&lt;child&gt; state             (pose of the shape in the compound body frame)</span></span>
<span class="line"><span>  &lt;attribute&gt; pos [Vec&lt;3&gt;]</span></span>
<span class="line"><span>  &lt;attribute&gt; (optional, default=1,0,0,0) quat [Vec&lt;4&gt;]</span></span></code></pre></div></li></ol><h3 id="mesh" tabindex="-1">mesh <a class="header-anchor" href="#mesh" aria-label="Permalink to &quot;mesh&quot;">​</a></h3><p><code>com</code> and the <code>inertia</code> child are required.</p><p><strong>attributes</strong>: <code>file_name</code> [string]: the mesh file, <code>scale</code> [Vec&lt;3&gt;]: mesh scale; only the first component is used (uniform scale), (optional, default=0) <code>collision_mode</code> [int]: <code>0</code> keeps the triangle mesh, <code>1</code> uses its convex hull, <code>2</code> uses a CoACD convex decomposition</p><ol><li>&lt;child&gt; (optional) <code>coacd</code>: CoACD parameters used with <code>collision_mode=&quot;2&quot;</code>. The attributes <code>threshold</code>, <code>max_hulls</code>, <code>preprocess</code>, <code>prep_resolution</code>, <code>sample_resolution</code>, <code>mcts_nodes</code>, <code>mcts_iterations</code>, <code>mcts_depth</code>, <code>pca</code>, <code>merge</code>, <code>decimate</code>, <code>max_vertices</code>, <code>extrude</code>, <code>extrude_margin</code>, <code>approximation</code>, <code>seed</code>, and <code>real_metric</code> map to the fields of <code>raisim::CoacdOptions</code>; omitted attributes keep their defaults.</li></ol><h3 id="ground" tabindex="-1">ground <a class="header-anchor" href="#ground" aria-label="Permalink to &quot;ground&quot;">​</a></h3><p><a href="https://github.com/raisimTech/raisim2Lib/blob/main/rsc/xmlScripts/material/material.xml" target="_blank" rel="noreferrer">Example</a></p><p>An infinite static plane. Its collision group is fixed, so only the mask can be set.</p><p><strong>attributes</strong>: <code>name</code> [string], (optional, default=0) <code>height</code> [float], (optional, default <code>default</code>) <code>material</code> [string], (optional, default=-1) <code>collision_mask</code>, (optional) <code>appearance</code> [string]</p><h3 id="heightmap" tabindex="-1">heightmap <a class="header-anchor" href="#heightmap" aria-label="Permalink to &quot;heightmap&quot;">​</a></h3><p><a href="https://github.com/raisimTech/raisim2Lib/tree/main/rsc/xmlScripts/heightMaps" target="_blank" rel="noreferrer">Examples</a></p><p><strong>attributes (all options)</strong>: <code>name</code> [string], (optional, default <code>default</code>) <code>material</code> [string], (optional) <code>appearance</code> [string], (optional, default=1) <code>collision_group</code>, (optional, default=-1) <code>collision_mask</code>, (optional, default=0) <code>center_x</code>, <code>center_y</code>, <code>center_z</code> [float], (optional, default=identity) <code>quat</code> [w, x, y, z]. <code>center_x</code> and <code>center_y</code> place the grid center in the height map&#39;s frame, <code>center_z</code> sets the position of that frame along z, and <code>quat</code> its orientation about the frame origin (see <a href="./HeightMap.html">Height Map</a>).</p><p>The height data comes from exactly one of the following options. If several are present, the first one in this list is used.</p><ol><li>Raw heights: <code>x_sample</code> [int], <code>y_sample</code> [int], (optional, default=10) <code>x_size</code> and <code>y_size</code> [float], and <code>height</code> [list of float] with <code>x_sample * y_sample</code> values.</li><li>Terrain generator: <code>x_sample</code> [int], <code>y_sample</code> [int], (optional, default=10) <code>x_size</code> and <code>y_size</code> [float], and a child <code>terrain_properties</code> (alias <code>terrainProperties</code>) with the attributes <code>frequency</code> [float], <code>z_scale</code> [float], <code>fractal_octaves</code> [int], <code>fractal_lacunarity</code> [float], <code>fractal_gain</code> [float], <code>step_size</code> [float], <code>seed</code> [int], and (optional, default=0) <code>height_offset</code> [float]. This option currently ignores <code>collision_group</code> and <code>collision_mask</code>.</li><li>PNG image: <code>png</code> [string], (optional, default=10) <code>x_size</code> and <code>y_size</code> [float], <code>z_scale</code> (alias <code>height_scale</code>) [float], and <code>z_offset</code> (alias <code>height_offset</code>) [float]. The sample counts come from the image resolution.</li><li>Text file: <code>text</code> [string], the path of a height-map text file, which also stores the sample counts and sizes.</li></ol><h3 id="articulatedsystem-articulated-system" tabindex="-1">articulatedSystem / articulated_system <a class="header-anchor" href="#articulatedsystem-articulated-system" aria-label="Permalink to &quot;articulatedSystem / articulated_system&quot;">​</a></h3><p><a href="https://github.com/raisimTech/raisim2Lib/blob/main/rsc/xmlScripts/heightMaps/heightMapUsingPng.xml" target="_blank" rel="noreferrer">Example</a></p><p>Both tag names are accepted by the XML reader. <code>articulatedSystem</code> is the canonical exported form.</p><p><strong>attributes</strong>: <code>name</code> [string], <code>urdf_path</code> [string], (optional, default=URDF directory) <code>res_dir</code> [string], (optional, default=1) <code>collision_group</code>, (optional, default=-1) <code>collision_mask</code>, (optional) <code>modules</code> [space-separated string list], (optional) <code>joint_order</code> [space-separated joint names]: redefines the joint order (a child joint cannot precede its parent), (optional, default=0) <code>collide_parent</code> [int]: 1 enables collisions between a link and its parent, (optional, default=0) <code>convexify_meshes</code> [int]: 1 treats the URDF collision meshes as convex shapes</p><p>A relative <code>urdf_path</code> is looked up in the working directory first and then relative to the folder of the XML file, also when that file is included by another. A URDF found in neither place is a fatal error.</p><ol><li>&lt;child&gt; <code>state</code>: &lt;attribute&gt; <code>qpos</code> [VecDyn], the generalized coordinate, (optional, default=zeros) <code>qvel</code> [VecDyn], the generalized velocity</li></ol><h3 id="object-class" tabindex="-1">object_class <a class="header-anchor" href="#object-class" aria-label="Permalink to &quot;object_class&quot;">​</a></h3><p><code>object_class</code> defines reusable object templates under the top-level <code>raisim</code> node. Each child node name becomes a class name that can be used as an object tag under <code>objects</code>.</p><p>Common class attributes are <code>type</code> [string] (an object type name such as <code>sphere</code>), (required for <code>sphere</code>, <code>box</code>, <code>capsule</code>, <code>cylinder</code>, <code>mesh</code>, and <code>compound</code>) <code>mass</code> [float], (optional) <code>material</code> [string], (optional) <code>com</code> [Vec&lt;3&gt;], and the optional child <code>inertia</code> with attributes <code>xx</code>, <code>xy</code>, <code>xz</code>, <code>yy</code>, <code>yz</code>, and <code>zz</code>.</p><p>Primitive classes use the child <code>dimension</code> with the same shape parameters as <code>dim</code>. Mesh classes use the child <code>file</code> with the attribute <code>name</code> and the child <code>scale</code> with the attributes <code>x</code>, <code>y</code>, and <code>z</code> (only <code>x</code> is used). Articulated-system classes use the attributes <code>urdf_path</code>, resolved like an articulated system&#39;s against the file that defines the class, and optional <code>res_dir</code>. Compound classes use the child <code>children</code>; each child element is named after a primitive type or another compound class and uses the attributes <code>object_param</code> [VecDyn] (the shape parameters: radius; radius and height; or x, y and z), <code>pos</code> [Vec&lt;3&gt;], optional <code>quat</code> [Vec&lt;4&gt;], optional <code>material</code>, and optional <code>appearance</code>.</p><p>An instance of a class under <code>objects</code> takes <code>name</code>, the collision attributes, <code>body_type</code>, <code>state</code>, and <code>exist</code> like the corresponding built-in type; its shape, mass, and material come from the class.</p><h3 id="round-trip-elements" tabindex="-1">Round-trip elements <a class="header-anchor" href="#round-trip-elements" aria-label="Permalink to &quot;Round-trip elements&quot;">​</a></h3><p><code>World::exportToXml</code> also writes the following elements so that an exported world reloads in the same state. They are rarely written by hand; generate them with <code>exportToXml</code>.</p><ul><li><code>deformable</code> and <code>granular</code> objects, with their particles, constraints, and particle materials.</li><li><code>tuning</code> child of an object: damping and gyroscopic mode of single bodies, the pose of <code>ground</code> and <code>heightmap</code> objects, and the integration scheme, control mode, PD gains, targets, and feedforward force of articulated systems (<code>kp</code>, <code>kd</code>, <code>qref</code>, <code>uref</code>, and <code>feedforward</code> are then required).</li><li><code>sensors</code> and <code>actuators</code> children of an articulated system. See <a href="./Sensors.html">Sensors</a> and <a href="./Actuators.html">Actuators</a>.</li></ul><h2 id="simulation-settings" tabindex="-1">Simulation settings <a class="header-anchor" href="#simulation-settings" aria-label="Permalink to &quot;Simulation settings&quot;">​</a></h2><p>The optional <code>simulation</code> element under <code>raisim</code> sets solver, contact-detection, and sleeping parameters. Every attribute is optional; omitted attributes keep the current values. Boolean attributes are written as <code>0</code> or <code>1</code>.</p><table tabindex="0"><thead><tr><th>Attributes</th><th>Setting</th></tr></thead><tbody><tr><td><code>world_time</code></td><td><code>World::setWorldTime</code></td></tr><tr><td><code>solver_order</code></td><td><code>World::setContactSolverIterationOrder</code></td></tr><tr><td><code>solver_iterations</code>, <code>solver_threshold</code></td><td>maximum contact-solver iterations and termination threshold (<code>World::setContactSolverParam</code>)</td></tr><tr><td><code>alpha_init</code>, <code>alpha_low</code>, <code>alpha_decay</code></td><td>accepted for compatibility; the solver ignores them</td></tr><tr><td><code>gjk_iterations</code>, <code>gjk_tolerance</code>, <code>epa_iterations</code>, <code>epa_tolerance</code>, <code>max_contacts</code></td><td><code>gjkMaxIterations</code>, <code>gjkTolerance</code>, <code>epaMaxIterations</code>, <code>epaTolerance</code>, <code>maxContactsPerPair</code> of <code>contact::ContactSettings</code></td></tr><tr><td><code>swept_ccd</code>, <code>ccd_min_speed</code>, <code>ccd_margin</code></td><td><code>sweptCcdEnabled</code>, <code>sweptCcdMinSpeed</code>, <code>sweptCcdSpeculativeMargin</code></td></tr><tr><td><code>broadphase</code></td><td>broadphase type: <code>0</code> = <code>None</code>, <code>1</code> = <code>Sap3Axis</code>, <code>2</code> = <code>MultiBoxPrune</code></td></tr><tr><td><code>mbp_min_x/y/z</code>, <code>mbp_max_x/y/z</code>, <code>mbp_cell_x/y/z</code>, <code>mbp_bounds</code>, <code>mbp_padding</code>, <code>mbp_max_axis</code>, <code>mbp_max_object</code></td><td><code>mbpWorldMin</code>, <code>mbpWorldMax</code>, <code>mbpCellSize</code>, <code>mbpUseWorldBounds</code>, <code>mbpPadding</code>, <code>mbpMaxCellsPerAxis</code>, <code>mbpMaxCellsPerObject</code> of <code>contact::BroadphaseSettings</code></td></tr><tr><td><code>sleeping</code>, <code>sleep_linear</code>, <code>sleep_angular</code>, <code>sleep_steps</code></td><td><code>World::setSleepingEnabled</code> and <code>World::setSleepingParameters</code></td></tr></tbody></table><p>See <a href="./WorldSystem.html">World</a> for the meaning and defaults of these settings.</p><h2 id="configuration-template" tabindex="-1">Configuration Template <a class="header-anchor" href="#configuration-template" aria-label="Permalink to &quot;Configuration Template&quot;">​</a></h2><p>Configuration templates build worlds systematically from parameters, loops, and reusable files. See <a href="https://github.com/raisimTech/raisim2Lib/blob/main/rsc/xmlScripts/templatedWorld/templatedWorld.xml" target="_blank" rel="noreferrer">templatedWorld.xml</a> and the <code>xml_templated_world</code> example, which loads it.</p><p><strong>Includes.</strong> <code>&lt;include value=&quot;[THIS_DIR]/terrain.xml&quot;/&gt;</code> loads another world file into the same world before the including file&#39;s own content. Use it to combine sub-worlds. Included files load in document order, and the settings of the including file (<code>material</code>, <code>gravity</code>, <code>timeStep</code>, <code>erp</code>, <code>simulation</code>) override theirs; a setting it does not name keeps the included file&#39;s value. The <code>value</code> may contain <code>@@</code> parameters. A relative path names a file in the working directory or, if there is none, a file relative to the folder of the including file, also inside a nested include. A missing file is a fatal error.</p><p>An include whose path ends in <code>.rscene</code> (in any letter case) builds a RaiSim Engine scene into the world, as <code>World(&quot;scene.rscene&quot;)</code> does, so a robot and the scene it runs in can live in separate files:</p><div class="language-xml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">xml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">raisim</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">include</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> value</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;[THIS_DIR]/../city/rayrai_city.rscene&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">objects</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">articulated_system</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;anymal&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> urdf_path</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;[THIS_DIR]/../anymal_c/urdf/anymal.urdf&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">            &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">state</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> qpos</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;...&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> qvel</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;...&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        &lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">articulated_system</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    &lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">objects</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">raisim</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><p>The scene sets its solver settings and contact materials, and adds its terrain, bodies and wires, before the robot. <code>World::getRscene()</code> returns the scene, so a rayrai <code>RayraiWindow</code> and the TCP viewer show its lights, sky, foliage and visual-only objects. A world holds at most one scene: a second <code>.rscene</code> include, also through an included XML file, is a fatal error. See <a href="./RsceneFile.html#a-robot-in-a-scene">A robot in a scene</a> and <a href="https://github.com/raisimTech/raisim2Lib/blob/main/rsc/xmlScripts/rscene/anymal_in_city.xml" target="_blank" rel="noreferrer">anymal_in_city.xml</a>.</p><p><strong>Parameters.</strong> A token <code>@@name</code> is replaced by the value of the parameter <code>name</code>. Define values in the file:</p><div class="language-xml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">xml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">params</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">object_spawn_height</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> value</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;0.3&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">params</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><p>or pass them to the constructor:</p><div class="language-cpp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">std</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">::vector</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">raisim</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">::</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">World</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">::ParameterContainer</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> params </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {{</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;floor_height&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;-1&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}};</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">raisim</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">::</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">World</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> world</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;templatedWorld.xml&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">params</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><p><code>&lt;params&gt;</code> values apply only to the file that defines them, while constructor values also apply to included files. A <code>&lt;params&gt;</code> value takes precedence over a constructor value with the same name. An <code>@@</code> token that is still unresolved after substitution is a fatal error.</p><p><strong>Loops.</strong> <code>&lt;array idx=&quot;@@i&quot; start=&quot;0&quot; end=&quot;9&quot; increment=&quot;1&quot;&gt; ... &lt;/array&gt;</code> repeats its content for <code>i = start, start + increment, ...</code> up to and including <code>end</code>, replacing every occurrence of the <code>idx</code> symbol with the integer value. <code>idx</code>, <code>start</code>, <code>end</code>, and <code>increment</code> are required; <code>start</code>, <code>end</code>, and <code>increment</code> must be integers (possibly supplied by parameters), <code>start</code> must not exceed <code>end</code>, and <code>increment</code> must be positive. Arrays can be nested. See <a href="https://github.com/raisimTech/raisim2Lib/blob/main/rsc/xmlScripts/templatedWorld/spheres.xml" target="_blank" rel="noreferrer">spheres.xml</a>.</p><p><strong>Math expressions.</strong> Text enclosed in <code>{}</code> is evaluated after parameters and loops are expanded and replaced by the result, e.g. <code>pos=&quot;{cos(0.1*@@i)} {sin(0.1*@@i)} 1&quot;</code>. Expressions support <code>+</code>, <code>-</code>, <code>*</code>, <code>/</code> with the usual precedence, parentheses, the functions <code>sin</code>, <code>cos</code>, <code>exp</code>, and <code>log</code>, and the constant <code>pi</code>. Write numbers in plain decimal notation; exponent notation such as <code>1e-3</code> is not supported. An expression that does not parse, such as an unmatched parenthesis or a function name without <code>(</code>, is a fatal error; this includes text in <code>{}</code> inside XML comments. The result is written as the shortest text that reads back as exactly the same number: a whole number has no decimal point (<code>name=&quot;link_{2*3}&quot;</code> becomes <code>link_6</code>), other values keep all their digits (<code>{1/3}</code> becomes <code>0.3333333333333333</code> and <code>{0.1+0.2}</code> <code>0.30000000000000004</code>), and very large or small magnitudes take an exponent (<code>1e-07</code>). A result that is not finite, such as <code>{1/0}</code>, is a fatal error.</p><p><strong>Conditional objects.</strong> An object with <code>exist=&quot;false&quot;</code> (or <code>&quot;False&quot;</code>) is skipped. Combined with a parameter, e.g. <code>exist=&quot;@@spawn_box&quot;</code>, this enables or disables objects at load time.</p>`,71)])])}const u=t(d,[["render",s]]);export{m as __pageData,u as default};
